function normalizePayload(value){
  if(value==null) return {};
  if(typeof value==='string'){
    const trimmed=value.trim();
    if(!trimmed) return {};
    try{return JSON.parse(trimmed);}catch{return {_raw_body:trimmed};}
  }
  if(typeof value==='object') return value;
  return {value};
}
function clean(value){return String(value||'').replace(/\s+/g,' ').trim();}
function stripLegalSuffix(value){
  return clean(value)
    .replace(/\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|co\.?|sdn\.?\s*bhd\.?)\b/gi,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function simplifySearchName(value){
  return clean(stripLegalSuffix(value))
    .replace(/\([^)]*\)/g,' ')
    .replace(/\s*@.*$/,' ')
    .replace(/\b(?:on\s+conference\s+leave|conference\s+leave|temporarily\s+closed|closed\s+temporarily|on\s+leave)\b.*$/i,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function hasCorporatePreference(value){
  return /\b(?:holdings?|group|pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation)\b/i.test(String(value||''));
}
function buildDomainClueQuery(value){
  const simplified=simplifySearchName(value).toLowerCase();
  const ignored=new Set(['pte','private','ltd','limited','llp','inc','corp','corporation','co','group','holdings','holding']);
  const tokens=simplified.replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter((token)=>token && !ignored.has(token));
  if(tokens.length===2 && tokens[0]==='singapore') return 'sg' + tokens[1] + ' singapore';
  return '';
}
const webhookPayload=(()=>{try{return $('Worker Webhook').item.json||{};}catch{return {};}})();
const source=Object.prototype.hasOwnProperty.call(webhookPayload||{},'body')?webhookPayload.body:(Object.prototype.hasOwnProperty.call($json||{},'body')?$json.body:$json);
const body=normalizePayload(source);
if(!body||!body.Id) throw new Error('Worker payload missing Id');
const companyName=clean(body.company_name||'');
if(!companyName) throw new Error('Worker payload missing company_name for Id '+body.Id);
const preferCorporateRoot=hasCorporatePreference(companyName);
const searchBaseName=stripLegalSuffix(companyName)||companyName;
const corporateSearchName=preferCorporateRoot ? simplifySearchName(stripLegalSuffix(companyName).replace(/\b(?:holdings?|group)\b/gi,' ')) : '';
const searchBackupName=corporateSearchName || simplifySearchName(companyName) || searchBaseName || companyName;
const safeExact=companyName.replace(/"/g,'').trim();
const safeBackup=String(searchBackupName||'').replace(/"/g,'').trim();
const domainClueQuery=preferCorporateRoot ? buildDomainClueQuery(companyName) : '';
