return {json:{
  ...body,
  Id:body.Id,
  company_name:companyName,
  prefer_corporate_root:preferCorporateRoot,
  search_exact_query:'"'+safeExact+'" Singapore',
  search_backup_query:safeBackup && safeBackup.toLowerCase()!==safeExact.toLowerCase() ? ('"'+safeBackup+'" Singapore') : '',
  search_broad_query:broadQuery,
  search_domain_query:domainClueQuery,
  hia_batch:clean(body.hia_batch)
}};

function hostFromUrl(value){
  const raw=String(value||'').trim();
  if(!raw)return '';
  const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;
  const match=withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1]||'').replace(/^www\./i,'').toLowerCase().trim();
}
function pathFromUrl(value){
  const raw=String(value||'').trim();
  if(!raw)return '/';
  const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;
  const match=withProtocol.match(/^(?:https?:\/\/)?[^/?#]+([^?#]*)/i);
  return String(match?.[1]||'/').toLowerCase() || '/';
}
function compact(value){
  return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'');
}
const input=$('Normalize Input').first().json || {};
const payload=$json || {};
const results=Array.isArray(payload.results) ? payload.results : (Array.isArray(payload.organic) ? payload.organic : []);
const generic=new Set(['singapore','limited','ltd','pte','private','company','group','holdings','holding','services','service','the','and']);
const tokens=String(input.company_name || '').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(t => t.length >= 3 && !generic.has(t));
const companyCompact=compact(input.company_name || '');
const blockedHosts=['baidu.com','facebook.com','instagram.com','linkedin.com','x.com','twitter.com','youtube.com','reddit.com','wikipedia.org','waze.com','streetdirectory.com','findhealthclinics.com','recordowl.com','asiafirms.com','apabuka.com','threebestrated.sg','doctorxdentist.com','yellowpages.com.sg','pmc.ncbi.nlm.nih.gov','ncbi.nlm.nih.gov','clinicgeek.com','classpcn.sg','zoominfo.com','jobstreet.com','jobsdb.com','indeed.com','glassdoor.com','crunchbase.com','pitchbook.com','healthcare.com.sg'];
const blockedHostKeywords=['directory','listing','marketplace','yellowpages','streetdirectory','recordowl','zoominfo','jobstreet','jobsdb','glassdoor','indeed','crunchbase','pitchbook'];
const blockedPathPattern=/(?:\/item\/|\/question\/|\/people\/|\/profile\/|\/company\/|\/listing\/|\/directory\/|\/content\/dam\/)/i;
const blockedExtensionPattern=/\.(?:pdf|docx?|xlsx?|pptx?|txt)$/i;
const listingPattern=/(?:directory|listing|marketplace|map|maps|location|locations|profile|company profile|business database|yellow pages|book now|reviews?|ratings?)/i;
let strongCount=0;
let noisyCount=0;
for(const row of results.slice(0,10)){
  const title=String(row?.title || '').toLowerCase();
  const snippet=String(row?.snippet || row?.content || '').toLowerCase();
  const url=String(row?.url || row?.link || '').trim();
  const host=hostFromUrl(url);
  const path=pathFromUrl(url);
  const text=[title,snippet,url.toLowerCase()].join(' ');
