  const tokenHits=tokens.filter(t => text.includes(t)).length;
  const exactTitle=Boolean(companyCompact && compact(title).includes(companyCompact));
  const exactSnippet=Boolean(companyCompact && compact(snippet).includes(companyCompact));
  const strongResult=(!blockedHost && !blockedDomain && !blockedPath && !blockedExtension && !noisyListing && !utilityBooking) && (exactTitle || exactSnippet || tokenHits >= 2);
  if(strongResult) strongCount += 1;
  if(blockedHost || blockedDomain || blockedPath || blockedExtension || noisyListing || utilityBooking) noisyCount += 1;
}
const weakSignal = results.length === 0 || strongCount === 0;
return { json: { ...payload, use_serper_homepage: weakSignal, searx_result_count: results.length, searx_strong_count: strongCount, searx_noisy_count: noisyCount } };

function normalizeCandidateUrl(value){
  const raw=String(value||'').trim();
  if(!raw)return '';
  const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;
  const match=withProtocol.match(/^(?:https?:\/\/)?([^\/?#]+)([^?#]*)/i);
  if(!match) return '';
  const host=String(match[1]||'').toLowerCase().trim();
  if(!host||!host.includes('.')) return '';
  let pathname=String(match[2]||'/').replace(/\/+/g,'/');
  if(!pathname.startsWith('/')) pathname='/' + pathname;
  if(pathname.length>1 && pathname.endsWith('/')) pathname=pathname.slice(0,-1);
  return 'https://' + host + (pathname||'/');
}
function normalizeRoot(value){
  const normalized=normalizeCandidateUrl(value);
  if(!normalized)return '';
  const match=normalized.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  const hostname=String(match?.[1]||'').toLowerCase().trim();
  if(!hostname)return '';
  return 'https://'+hostname+'/';
}
function canonicalDomain(value){
  const root=normalizeRoot(value);
  const match=root.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1]||'').replace(/^www\./i,'').toLowerCase().trim();
}
function pathnameFromUrl(value){
  const normalized=normalizeCandidateUrl(value);
  let pathname='/';
  try {
    const raw=String(normalized || value || '');
    const match=raw.match(/^https?:\/\/[^/]+(\/[^?#]*)/i);
    pathname=String(match?.[1] || '/');
  } catch {
    pathname='/';
  }
  pathname=String(pathname||'/').toLowerCase().replace(/\/+/g,'/');
  if(!pathname.startsWith('/')) pathname='/' + pathname;
  if(pathname.length>1 && pathname.endsWith('/')) pathname=pathname.slice(0,-1);
  return pathname || '/';
}
function registrableLabel(hostname){
  const labels=String(hostname||'').split('.').filter(Boolean);
  if(labels.length>=3&&labels[labels.length-1]==='sg'&&['com','org','net','edu','gov'].includes(labels[labels.length-2])) return labels[labels.length-3]||'';
  return labels[labels.length-2]||labels[0]||'';
}
function compact(value){ return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,''); }
function tokens(value){ return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(Boolean); }
function tokenWords(value){
  return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(Boolean);
}
function extractResults(payload){
  const organic = Array.isArray(payload?.organic) ? payload.organic : [];
  const results = Array.isArray(payload?.results) ? payload.results : [];
  return organic.length ? organic : results;
}
function cleanInput(value){
  return String(value||'')
    .replace(/\([^)]*\)/g,' ')
    .replace(/\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|co\.?|sdn\.?\s*bhd\.?)\b/gi,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function tokenVariants(token){
  const normalized=compact(token);
  if(!normalized) return [];
  if(normalized==='singapore') return ['singapore','sg'];
  return [normalized];
}
function tokenMatchCount(haystacks, tokenList){
  const matched=new Set();
  const haystackWords=haystacks.map((value)=>new Set(tokenWords(value)));
  for(const token of tokenList){
    const variants=tokenVariants(token);
    if(!variants.length) continue;
    if(haystackWords.some((wordSet)=>variants.some((variant)=>wordSet.has(variant)))) matched.add(compact(token));
  }
  return matched.size;
}
function extractMentionedDomains(text){
  const matches=String(text||'').toLowerCase().match(/\b(?:https?:\/\/)?(?:www\.)?[a-z0-9-]+(?:\.[a-z0-9-]+){1,3}\b/g) || [];
  const domains=[];
  const seen=new Set();
  for(const raw of matches){
    const cleaned=String(raw||'').replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/[).,;:]+$/,'').trim();
    if(!cleaned || !cleaned.includes('.') || !/[a-z]/.test(cleaned)) continue;
    const labels=cleaned.split('.').filter(Boolean);
    const rootLabel=registrableLabel(cleaned);
    if(labels.length < 2) continue;
    if(labels.some((label)=>label.length < 2)) continue;
    if(String(labels[labels.length-1] || '').length < 2) continue;
    if(String(rootLabel || '').length < 3) continue;
    if(seen.has(cleaned)) continue;
    seen.add(cleaned);
    domains.push(cleaned);
  }
  return domains;
}
const BLOCKED_HOSTS=['baidu.com','facebook.com','instagram.com','linkedin.com','x.com','twitter.com','youtube.com','yellowpages.com.sg','streetdirectory.com','findhealthclinics.com','wherecrowded.sg','recordowl.com','doctorxdentist.com','waze.com','google.com','maps.apple.com','moh.gov.sg','healthhub.sg','acra.gov.sg','gobusiness.gov.sg','straitstimes.com','todayonline.com','channelnewsasia.com','businessinsider.com','techinasia.com','tripadvisor.com','foursquare.com','yelp.com','practo.com','threebestrated.sg','contact.page','neighbourhoodshop.sg','tracxn.com','hotfrog.sg','infobel.sg','zipleaf.com','companies.sg','sgpbusiness.com','keepital.com','healthcare.com.sg','pmc.ncbi.nlm.nih.gov','ncbi.nlm.nih.gov','zoominfo.com','jobstreet.com','jobsdb.com','indeed.com','glassdoor.com','crunchbase.com','pitchbook.com','scam.sg','reddit.com','scribd.com','propertyguru.com.sg','bharatopd.com','getdoc.com','clinicgeek.com','babyment.com','visittiongbahru.com','nourkrin.com.sg','99.co','sg.finance.yahoo.com','finance.yahoo.com','yahoo.com','bloomberg.com','reuters.com','morningstar.com','tradingview.com','sgx.com'];
const BLOCKED_HOST_KEYWORDS=['directory','listing','marketplace','yellowpages','streetdirectory','recordowl','zoominfo','jobstreet','jobsdb','glassdoor','indeed','crunchbase','pitchbook','scam','forum','reddit','propertyguru','scribd','bharatopd','moovit'];
const BLOCKED_PATH=/(?:\/item\/|\/question\/|\/people\/|\/profile\/|\/company\/|\/listing\/|\/directory\/|\/content\/dam\/|\/job\/|\/jobs\/|\/document\/)/i;
const BLOCKED_EXTENSION=/\.(?:pdf|docx?|xlsx?|pptx?|txt)$/i;
const LISTING_HINT=/(?:directory|listing|reviews?|rating|opening hours|postal code|address|company profile|business database|profile, contacts|contact details|marketplace|book now|appointment|book appointment|yellow pages|local businesses|google rating|top rated|company data|store locator|poi|map|maps|aggregator|overview, news & similar companies|property|real estate|hdb|condo|for sale|for rent|classified|stock|quote|share price|market data|yahoo finance|bloomberg|reuters|morningstar|sgx|how to get to|public transportation)/i;
const UTILITY_PATH=/(?:\/(?:author|tag|category|blog|news|article|articles|faq|faqs|guide|policy|privacy|terms|career|careers|events?|latest-events|downloads?|resources?|contact-us|contact|get-in-touch|about-us|about|investor-relations|ir)\b)/i;
