const GENERIC_TOKENS=new Set(['singapore','official','website','services','service','the','and']);
const LEGAL_SUFFIX_TOKENS=new Set(['pte','private','ltd','limited','llp','inc','corp','corporation','co']);
const input=$('Normalize Input').first().json || {};
const companyName=String(input.company_name || '').trim();
const anchorName=cleanInput(companyName);
