const rawTokens=tokens(companyName).filter((token)=>token.length>=3 && !GENERIC_TOKENS.has(token) && !LEGAL_SUFFIX_TOKENS.has(token));
const preferCorporateRoot=Boolean(input.prefer_corporate_root);
const matchingTokens=anchorTokens.length ? anchorTokens : (companyCompact ? [companyCompact] : []);
const corporateTokens=preferCorporateRoot ? Array.from(new Set([...matchingTokens, ...rawTokens])) : matchingTokens;
const seedRows=[];
for(const [index, result] of rawRows.entries()){
  const title=String(result?.title||'').trim();
  const snippet=String(result?.snippet||result?.content||'').trim();
  const sourceRank=Number(result?.position || result?.rank || index + 1);
  const rawUrl=String(result?.link || result?.url || '').trim();
