  const pathTokenHits=tokenMatchCount([pathCompact,pathname], matchingTokens);
  const corporateTokenHits=preferCorporateRoot ? tokenMatchCount([domainText,titleCompact,title,snippetCompact,snippet,pathCompact,pathname], corporateTokens) : 0;
  const domainSignal=Boolean(companyCompact && domainText.includes(companyCompact)) || domainTokenHits>=2;
