  const strongIdentity = domainSignal || (titleSignal && snippetSignal) || (clueCandidate && rootLabelHits>=1 && (snippetSignal || titleSignal)) || (rootLabelHits>=1 && titleSignal) || officialEvidencePage || branchEvidenceHint;
  const thirdPartyHint = listingHint || (!officialEvidencePage && !branchEvidenceHint && !domainSignal && !clueCandidate && rootLabelHits===0 && !corporateSignal);
  if(!strongIdentity) continue;
  if(thirdPartyHint && !domainSignal && !clueCandidate && !officialEvidencePage && !branchEvidenceHint) continue;
