  if(titleSignal) evidenceScore += 4;
  if(snippetSignal) evidenceScore += 2;
  if(pathSignal) evidenceScore += 1;
  if(rootCandidate) evidenceScore += 1;
  if(clueCandidate) evidenceScore += 2;
  if(officialEvidencePage) evidenceScore += 2;
  if(branchEvidenceHint) evidenceScore += 2;
