  candidates.push({
    rank: sourceRank,
    source_rank: sourceRank,
    url: normalizedUrl,
    homepage_root: root,
    canonical_domain: domain,
    title,
    snippet,
    domain_signal: domainSignal,
    title_signal: titleSignal,
    snippet_signal: snippetSignal,
