function clean(value){return String(value||'').replace(/\s+/g,' ').trim();}
function stripFences(value){const fence=String.fromCharCode(96).repeat(3);return String(value||'').split(fence+'json').join('').split(fence).join('').trim();}
function cleanName(value){
  return clean(value)
    .replace(/^\s*(?:welcome to|official site of|home of)\s+/i,'')
    .replace(/\s*[|–—-]\s*(?:official|homepage|home).*$/i,'')
    .replace(/\([^)]*\)/g,' ')
    .replace(/\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|co\.?)\b/gi,' ')
    .replace(/\s+/g,' ')
